import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { anchors, receiptId, rules, run, spec } from "./index.mjs";

const read = (f) => JSON.parse(readFileSync(new URL(f, import.meta.url), "utf8"));
const { cases } = read("./cases.json");
const figures = read("./rules.json");
const json = (v) => JSON.parse(JSON.stringify(v));

test("rules.json lists exactly the figures in the code", () => {
  assert.deepEqual(figures.rules.map(({ skill_url, ...r }) => r), json(rules));
  for (const r of figures.rules) assert.equal(r.skill_url, `https://www.openaccountants.com/skills/${r.slug}`);
  assert.equal(figures.spec.name, spec.name);
  assert.equal(figures.spec.version, spec.version);
  assert.deepEqual(figures.spec.tax_years, spec.tax_years);
  assert.deepEqual(figures.anchors, anchors);
});

for (const c of cases) {
  test(`${c.id}: ${c.expected.status}`, () => {
    const out = run(c.inputs);
    assert.deepEqual(json(out), c.expected);
    for (const used of out.constants_used ?? []) {
      assert.ok(figures.rules.some(({ skill_url, ...r }) => JSON.stringify(r) === JSON.stringify(used)), `${used.name} is not in rules.json`);
    }
    for (const a of out.skill_anchors_reproduced ?? []) assert.ok(anchors.includes(a), a);
    if (c.receipt_id) assert.equal(receiptId(spec.name, spec.version, c.inputs, out), c.receipt_id);
  });
}
